use harbor.signal;

fn entries() -> String {
    let signals = signal.all();
    var out = "";
    var first = true;
    var i = 0;
    while i < signals.len() {
        let rendered = match signals.get(i) {
            signal.Calm => "calm",
            signal.Gale(speed) => concat(other: "gale:", other: speed.to_text()),
            signal.Fog(density) => concat(other: "fog:", other: density),
        };
        out = match first {
            true => rendered,
            false => concat(other: out, other: ";", other: rendered),
        };
        first = false;
        i = i + 1;
    }
    out
}

use mill.stock;
use mill.rules;

fn lines() -> String {
    let planks = stock.planks();
    var result = "";
    var first = true;
    var i = 0;
    while i < planks.len() {
        let plank = planks[i];
        if rules.keeps(plank) {
            if first {
                result = result.concat(other: rules.label(plank));
                first = false;
            } else {
                result = result.concat(other: ",");
                result = result.concat(other: rules.label(plank));
            }
        }
        i = i + 1;
    }
    result
}

