use mill.stock;
use mill.rules;

pub fn lines() -> String {
    let planks = mill.stock.inventory();
    var result = "";
    var first = true;
    var i = 0;
    while i < planks.len() {
        let maybe_plank = planks.get(index: i);
        match maybe_plank {
            Some(plank) => {
                if mill.rules.keeps(plank) {
                    if first {
                        result = result.concat(other: mill.rules.label(plank));
                        first = false;
                    } else {
                        result = result.concat(other: ",");
                        result = result.concat(other: mill.rules.label(plank));
                    }
                }
            }
            None => unit,
        };
        i = i + 1;
    }
    result
}
